// localStorage key read by index.html's pre-React splash to localize its title
const LANGUAGE_HINT_STORAGE_KEY = 'Wulu-language';

// 鍒濆鍖栧畬鎴愬墠鐨勮瑷€锛氫紭鍏堜笂娆″惎鍔ㄦ寔涔呭寲鐨勬彁绀猴紝鍏舵绯荤粺璇█锛堜笌 splash 鐨勬帹鏂€昏緫涓€鑷达級
const readLanguageHint = (): LanguageType => {
  try {
    const hint = localStorage.getItem(LANGUAGE_HINT_STORAGE_KEY);
    if (hint === 'zh' || hint === 'en') {
      return hint;
    }
    return navigator.language === 'zh-CN' ? 'zh' : 'en';
  } catch {
    return 'zh';
  }
};

class I18nService {
  private currentLanguage: LanguageType = 'zh';
  private listeners = new Set<() => void>();

  constructor() {
    this.currentLanguage = readLanguageHint();
  }

  // 鍒濆鍖栬瑷€璁剧疆
  async initialize(): Promise<void> {
    try {
      const config = configService.getConfig();

      // 妫€鏌ユ槸鍚﹀凡缁忓垵濮嬪寲杩囪瑷€璁剧疆
      const languageInitialized = config.language_initialized;

      if (languageInitialized !== true) {
        // 鍙兘鏄娆″惎鍔ㄦ垨鏃х増鏈敤鎴峰崌绾?
        // 涓轰簡淇濇姢鏃х敤鎴风殑璇█璁剧疆,妫€鏌ユ槸鍚︽湁闈為粯璁ょ殑璇█閰嶇疆
        const hasCustomLanguage = config.language && config.language !== 'zh';

        if (hasCustomLanguage) {
          // 鏃х敤鎴峰凡鎵嬪姩璁剧疆杩囪瑷€(闈為粯璁ゅ€?,淇濈暀浠栦滑鐨勮缃?
          console.log(`[i18n] Legacy user detected with custom language: ${config.language}`);
          this.currentLanguage = config.language;
          configService.updateConfig({
            language_initialized: true,
          });
        } else {
          // 鏂扮敤鎴锋垨浣跨敤榛樿涓枃鐨勬棫鐢ㄦ埛:妫€娴嬬郴缁熻瑷€
          try {
            const systemLocale = await window.electron.appInfo.getSystemLocale();
            const defaultLanguage = this.inferLanguageFromLocale(systemLocale);

            console.log(
              `[i18n] First run detected. System locale: ${systemLocale}, default language: ${defaultLanguage}`,
            );

            this.currentLanguage = defaultLanguage;

            // 淇濆瓨璇█閰嶇疆鍜屽垵濮嬪寲鏍囪
            configService.updateConfig({
              language: defaultLanguage,
              language_initialized: true,
            });
          } catch (error) {
            console.error('Failed to get system locale:', error);
            // 濡傛灉鑾峰彇绯荤粺璇█澶辫触,榛樿浣跨敤鑻辨枃
            this.currentLanguage = 'en';
            configService.updateConfig({
              language: 'en',
              language_initialized: true,
            });
          }
        }
      } else {
        // 闈為娆″惎鍔?浣跨敤宸蹭繚瀛樼殑璇█閰嶇疆
        if (config.language && (config.language === 'zh' || config.language === 'en')) {
          this.currentLanguage = config.language;
        } else {
          // 濡傛灉閰嶇疆鏃犳晥,fallback 鍒拌嫳鏂?
          this.currentLanguage = 'en';
          configService.updateConfig({
            language: 'en',
          });
        }
      }
    } catch (error) {
      console.error('Failed to initialize language:', error);
      // 榛樿浣跨敤鑻辨枃
      this.currentLanguage = 'en';
    }
    this.persistLanguageHint(this.currentLanguage);
  }

  // 鎸佷箙鍖栬瑷€鎻愮ず锛屼緵 index.html 鐨勫惎鍔ㄥ睆鍦ㄤ笅娆″惎鍔ㄦ椂璇诲彇
  private persistLanguageHint(language: LanguageType): void {
    try {
      localStorage.setItem(LANGUAGE_HINT_STORAGE_KEY, language);
    } catch { /* storage unavailable */ }
  }

  // 鏍规嵁绯荤粺璇█鎺ㄦ柇搴旂敤璇█
  private inferLanguageFromLocale(systemLocale: string): LanguageType {
    // 鍙湁 zh-CN (绠€浣撲腑鏂? 鎵嶄娇鐢ㄤ腑鏂?鍏朵粬鎵€鏈夋儏鍐甸兘浣跨敤鑻辨枃
    if (systemLocale === 'zh-CN') {
      return 'zh';
    }
    return 'en'; // 榛樿鑻辨枃 (鍖呮嫭 zh-TW, zh-HK, en-*, 浠ュ強鍏朵粬鎵€鏈夎瑷€)
  }

  // 璁剧疆璇█
  setLanguage(language: LanguageType, options: { persist?: boolean } = {}): void {
    const { persist = true } = options;
    const hasChanged = this.currentLanguage !== language;
    this.currentLanguage = language;

    if (hasChanged) {
      this.listeners.forEach(listener => listener());
    }

    if (!persist) {
      return;
    }

    this.persistLanguageHint(language);

    // 鏇存柊閰嶇疆
    try {
      const config = configService.getConfig();
      configService.updateConfig({
        ...config,
        language,
      });
    } catch (error) {
      console.error('Failed to save language setting:', error);
    }
  }

  // 鑾峰彇褰撳墠璇█
  getLanguage(): LanguageType {
    return this.currentLanguage;
  }

  // 鑾峰彇缈昏瘧鏂囨湰
  t(key: string): string {
    const translation = translations[this.currentLanguage][key];
    if (!translation) {
      console.warn(`Translation missing for key: ${key} in language: ${this.currentLanguage}`);
      // 灏濊瘯浠庡彟涓€绉嶈瑷€鑾峰彇
      const fallbackTranslation = translations[this.currentLanguage === 'zh' ? 'en' : 'zh'][key];
      return fallbackTranslation || key;
    }
    return translation;
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }
}

export const i18nService = new I18nService();
